template <typename UnionPtrType>
UserImagePtr UserImage::Clone() const {
  switch (tag_) {
    case Tag::kDefaultImage:
      return NewDefaultImage(
          mojo::Clone(*data_.default_image));
    case Tag::kExternalImage:
      return NewExternalImage(
          mojo::Clone(*data_.external_image));
    case Tag::kProfileImage:
      return NewProfileImage(
          mojo::Clone(*data_.profile_image));
    case Tag::kInvalidImage:
      return NewInvalidImage(
          mojo::Clone(*data_.invalid_image));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, UserImage>::value>::type*>
bool UserImage::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kDefaultImage:
      return mojo::Equals(*(data_.default_image), *(other.data_.default_image));
    case Tag::kExternalImage:
      return mojo::Equals(*(data_.external_image), *(other.data_.external_image));
    case Tag::kProfileImage:
      return mojo::Equals(*(data_.profile_image), *(other.data_.profile_image));
    case Tag::kInvalidImage:
      return mojo::Equals(*(data_.invalid_image), *(other.data_.invalid_image));
  }

  return false;
}
